console.log("Proof artifact: " + DATA.artifact);
var links = DATA.links.split("|").map(function (s) { return s.trim(); });
var prev = "GENESIS", ok = true;
console.log("--- verifying chain ---");
links.forEach(function (link, i) {
  var h = hash(prev + "|" + link);
  console.log("  link " + (i + 1) + ": " + link + "  hash=" + h);
  prev = h;
});
DATA.steps.split("|").forEach(function (s, i) { console.log("  verify step " + (i + 1) + ": " + s.trim() + " — OK"); });
console.log("RESULT: proof verified — chain head " + prev + "; claim '" + DATA.claim + "' holds.");

